#define PHONELM_PRECISION_LIBRARY
#include "upstream_precision_test.cpp"
#include "double_qk_fixture.h"
#include <fstream>
#include <sstream>
// Offline analysis only. Actual gradients here are HOST_CONDITIONED_ON_DEVICE_P,
// never evidence of DSP Backward execution.
int main(int argc,char** argv){std::cout<<std::setprecision(17);try{if(argc!=4)return 1;auto original=one::read(argv[1]);auto cs=doubleqkfixture::load(argv[2]);auto core=upstreamreference::fullUpstream(original);std::vector<std::array<precision::Gradient,2>> gs;
 for(auto& z:core){auto ref=one::reference(z,true);std::array<precision::Gradient,2> g;for(unsigned h=0;h<2;++h){auto p="h"+std::to_string(h)+"_";g[h]={ref.at(p+"dp"),ref.at(p+"dc")};}gs.push_back(g);}if(gs.size()!=25)throw std::runtime_error("gradient coverage");auto hold=precision::syntheticGradients();
 using Key=std::tuple<unsigned,unsigned,unsigned,unsigned>;std::map<Key,one::Vec> ps;bool host=std::string(argv[3])=="--host",shift=std::string(argv[3])=="--host-shift";
 if(host||shift){for(unsigned o=0;o<2;++o)for(unsigned t=0;t<2;++t)for(unsigned ci=0;ci<60;++ci)for(unsigned h=0;h<2;++h)ps[{o,t,ci,h}]=one::d(shift?forwardsoftmaxreference::evaluate(cs[ci].masked[h]).p:cs[ci].hostP[h]);}
 else {std::ifstream f(argv[3]);if(!f)throw std::runtime_error("device evidence open");std::string line;while(std::getline(f,line)){if(line.rfind("p_words,",0)!=0)continue;std::stringstream ss(line);std::string field;std::getline(ss,field,',');unsigned id[4];for(auto& v:id){if(!std::getline(ss,field,','))throw std::runtime_error("P identity parse");v=std::stoul(field);}if(id[0]>1||id[1]>1||id[2]>=60||id[3]>1)throw std::runtime_error("P identity range");one::Vec p;while(std::getline(ss,field,',')){if(!field.empty()&&field.back()=='\r')field.pop_back();if(field.size()!=8)throw std::runtime_error("P word parse");uint32_t bits=std::stoul(field,nullptr,16);p.push_back(double(forwardsoftmaxreference::number(bits)));}if(p.size()!=1024||!ps.emplace(Key{id[0],id[1],id[2],id[3]},p).second)throw std::runtime_error("P words duplicate/size");}}
 if(ps.size()!=480)throw std::runtime_error("P graph/case coverage incomplete");unsigned allFailures=0,variants=0;double worstLocal=0,worstP=0,worstDs=0,worstDv=0,worstDsActual=0,worstDvActual=0;
 for(unsigned o:{1u,0u})for(unsigned t:{1u,0u})for(unsigned ri=0;ri<2;++ri){precision::Totals totals[2];unsigned expectedWords=0,shiftWords=0;for(unsigned ci=0;ci<60;++ci){auto& c=cs[ci];auto& gradients=ci<44?gs:hold;unsigned set=ci<44?0:1;for(unsigned h=0;h<2;++h){auto& p=c.idealP[ri][h];auto& x=ps.at({o,t,ci,h});auto st=attribution::stats(p,x);totals[set].probability(ci,h,st);double local=attribution::distance(c.localP[h],x);worstLocal=std::max(worstLocal,local);auto shiftP=forwardsoftmaxreference::evaluate(c.masked[h]).p;unsigned diff=0;for(unsigned i=0;i<1024;++i){expectedWords+=forwardsoftmaxreference::bits(float(x[i]))!=forwardsoftmaxreference::bits(c.hostP[h][i]);shiftWords+=forwardsoftmaxreference::bits(float(x[i]))!=forwardsoftmaxreference::bits(shiftP[i]);diff+=forwardsoftmaxreference::bits(float(x[i]))!=forwardsoftmaxreference::bits(float(ps.at({1,1,ci,h})[i]));}if(!ri)variants+=diff;
   std::cout<<"{\"kind\":\"p_case\",\"observed\":"<<o<<",\"tap\":"<<t<<",\"reference\":\""<<(ri?"legacy":"source")<<"\",\"set\":"<<set<<",\"forward\":"<<ci<<",\"head\":"<<h<<",\"p_maxAbs\":"<<st.abs<<",\"p_rms\":"<<st.rms<<",\"row_error\":"<<st.rows<<",\"coordinate\":"<<st.coordinate<<",\"local_softmax_error\":"<<local<<",\"variant_word_mismatches\":"<<diff<<"}\n";
   for(unsigned gi=0;gi<gradients.size();++gi){auto& g=gradients[gi][h];auto b=attribution::impact(g.dp,g.dc,p,x);totals[set].add(ci,h,b);std::cout<<"{\"kind\":\"p_pair\",\"observed\":"<<o<<",\"tap\":"<<t<<",\"reference\":\""<<(ri?"legacy":"source")<<"\",\"set\":"<<set<<",\"forward\":"<<ci<<",\"head\":"<<h<<",\"gradient\":"<<gi;attribution::impactFields(b);std::cout<<"}\n";
    bool critical=ci<44&&((h==1&&(ci==16||ci==17||ci==20||ci==21||ci==22))||(h==0&&ci==22))&&(gi==9||gi==12);if(critical){unsigned row=st.coordinate/32;auto logits=c.masked[h];std::vector<float> sorted(logits.begin()+row*32,logits.begin()+(row+1)*32);std::sort(sorted.begin(),sorted.end(),std::greater<float>());std::cout<<"{\"kind\":\"critical_case\",\"observed\":"<<o<<",\"tap\":"<<t<<",\"reference\":\""<<(ri?"legacy":"source")<<"\",\"forward\":"<<ci<<",\"head\":"<<h<<",\"gradient\":"<<gi<<",\"p_coordinate\":"<<st.coordinate<<",\"row\":"<<row<<",\"host_masked_top2_gap\":"<<double(sorted[0])-double(sorted[1])<<",\"ds_budget_exceeded\":"<<(b.dsBound>.00025?"true":"false");attribution::impactFields(b);std::cout<<",\"row_p_reference\":";attribution::array(one::Vec(p.begin()+row*32,p.begin()+(row+1)*32));std::cout<<",\"row_p_actual\":";attribution::array(one::Vec(x.begin()+row*32,x.begin()+(row+1)*32));std::cout<<"}\n";}
   }
  }}for(unsigned set=0;set<2;++set){auto& z=totals[set];allFailures+=z.failures();worstP=std::max(worstP,z.p);worstDs=std::max(worstDs,z.ds);worstDv=std::max(worstDv,z.dv);worstDsActual=std::max(worstDsActual,z.dsActual);worstDvActual=std::max(worstDvActual,z.dvActual);std::string label="O"+std::to_string(o)+"T"+std::to_string(t);z.print(label,set?"holdout":"frozen",ri?"legacy":"source");}
  std::cout<<"{\"kind\":\"host_softmax_comparison\",\"observed\":"<<o<<",\"tap\":"<<t<<",\"reference\":\""<<(ri?"legacy":"source")<<"\",\"original_model_word_differences\":"<<expectedWords<<",\"fp32_shift_model_word_differences\":"<<shiftWords<<"}\n";
 }
 std::cout<<"{\"kind\":\"assessment_summary\",\"mode\":\""<<(host?"HOST_S2_C6":shift?"HOST_FP32_SHIFT":"HOST_CONDITIONED_ON_DEVICE_P")<<"\",\"DSP_BACKWARD_NOT_EXECUTED\":true,\"p_outputs\":"<<ps.size()<<",\"core_pairs_per_variant_reference\":2200,\"holdout_pairs_per_variant_reference\":256,\"required_failed_predicates\":"<<allFailures<<",\"variant_word_mismatches\":"<<variants<<",\"p_maxAbs\":"<<worstP<<",\"softmax_local_maxAbs\":"<<worstLocal<<",\"ds_bound\":"<<worstDs<<",\"dv_bound\":"<<worstDv<<",\"ds_actual\":"<<worstDsActual<<",\"dv_actual\":"<<worstDvActual<<",\"bound_identity_checks\":true,\"joint_pass\":"<<(allFailures?"false":"true")<<"}\n";return allFailures||variants?4:0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 5;}}
